def f(g):
    H,W=len(g),len(g[0])
    cnt=[[0]*W for _ in range(H)]
    lr=[r for r in range(H) if all(x==2 for x in g[r])][0]
    for r in range(H):
        for c in range(W):
            if g[r][c]==4 and r!=lr:
                dist=abs(r-lr); away=-1 if r<lr else 1
                for h,hh in ((dist+1,lr+away),(dist,r)):
                    for d in range(h):
                        rr=hh+away*d
                        if 0<=rr<H:
                            for cc in range(c-d,c+d+1):
                                if 0<=cc<W: cnt[rr][cc]+=1
    out=[[2 if x==2 else (4 if cnt[r][c]%2 else 0) for c,x in enumerate(row)] for r,row in enumerate(g)]
    return out
