    lr=[r for r in range(H) if all(x==2 for x in g[r])][0]
    cells=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==4 and r!=lr:
                v=r+1
                cells.append((v,c))
                if abs(v-lr)==1:
                    aw=1 if v>lr else -1
                    for dc in (-1,1):
                        rr,cc=v,c
                        while True:
                            rr+=aw; cc+=dc
                            if not(0<=rr<H and 0<=cc<W): break
                            cells.append((rr,cc))
    out=[[0]*W for _ in range(H)]
    for r,c in cells: out[r][c]=4
    for c in range(W): out[lr][c]=2
    return out
